import {createTraffic,stepTraffic,perception,signalState,requestDog,trafficSummary,validateTrafficModel,TRAFFIC_VERSION} from './road-core.js';
import {RoadScene} from './road-scene.js';
const $=id=>document.getElementById(id),colors=['#cbdc72','#db8262','#82b7c1','#dedbd0','#a79bc2','#b9b9b1','#e2bc68','#70a99c'],storageKey='vector-road-policy-v1';
let model=null,baseline=null,report=null,baselineReport=null,scene=null,selected=0,view='overview',worker=null,busy=false,running=false,world=createTraffic({seed:73}),history=[],lastHistorySecond=-1;
const num=(v,d=0)=>Number(v||0).toFixed(d),pad=n=>String(n).padStart(2,'0'),clock=t=>`${pad(Math.floor(t/60))}:${pad(Math.floor(t%60))}`;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function status(message,percent){$('road-training-status').textContent=message;if(percent!==undefined)$('road-training-bar').style.width=`${percent}%`;}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({model,report}));}catch{toast('Local storage is full. Export your Road model to keep it.');}}
function setRunning(value){running=!!value&&!!model&&!busy;world.paused=!running;$('run-traffic').textContent=running?'Ⅱ Pause traffic':'▶ Start traffic';$('top-status').textContent=busy?'Learning job in progress':running?'Traffic simulation live':'Traffic paused';}
function settings(){return {count:Number($('car-count').value),mode:$('fleet-mode').value,supervisor:$('supervisor-toggle').checked,seed:73};}
function reset(autoplay=running){world=createTraffic(settings());selected=Math.min(selected,world.cars.length-1);history=[];lastHistorySecond=-1;scene?.resetFleet(world);buildFleet();selectCar(selected,view);setRunning(autoplay);updateUI();}
function buildFleet(){const list=$('fleet-list');list.replaceChildren();for(const car of world.cars){const button=document.createElement('button');button.className='car-card';button.setAttribute('aria-label',`Select Car ${pad(car.id+1)} viewpoint`);button.innerHTML=`<span class="car-swatch" style="background:${colors[car.id%colors.length]}"></span><div><b>Car ${pad(car.id+1)}</b><small>Lane ${car.lane+1} · independent agent</small></div><span>0<small>KM/H</small></span>`;button.addEventListener('click',()=>selectCar(car.id,'chase'));list.append(button);} $('fleet-count').textContent=`${world.cars.length} AGENTS`;}
function selectCar(id,nextView='chase'){selected=id;view=nextView;scene?.select(id,view);document.querySelectorAll('.car-card').forEach((b,i)=>{b.classList.toggle('selected',i===selected);b.setAttribute('aria-pressed',String(i===selected));});document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});$('overview-side').classList.toggle('selected',view==='overview');$('view-label').textContent=view==='overview'?'CITY OVERVIEW':`${view==='pov'?'DRIVER POV':'FOLLOW CAMERA'} / CAR ${pad(selected+1)}`;$('view-subtitle').textContent=view==='overview'?'Every car predicts its own steering and pedal inputs.':view==='pov'?'Live driver view. Click another car in the fleet panel to switch.':'Click a car in the scene or fleet panel to ride along.';$('selected-car-label').textContent=`CAR ${pad(selected+1)}`;updateUI();}
function metric(id,value,incident=false){$(id).textContent=value;$(id).parentElement.classList.toggle('incident',incident);}
function updateUI(){if(!world)return;const s=world.stats,c=world.cars[selected],p=c.observation||perception(world,c);
 $('road-time').textContent=clock(world.time);$('scene-agents').textContent=`${world.cars.length} cars · ${world.actors.filter(a=>a.kind==='person').length} people · ${world.actors.filter(a=>a.kind==='dog').length} dogs`;
 $('controller-label').textContent=`${world.mode==='neural'?'NEURAL FLEET':'SCRIPTED EXPERT'}${world.supervisor?' + BRAKING SUPERVISOR':' / UNASSISTED'}`;
 metric('vehicle-contacts',s.vehicleContacts,s.vehicleContacts>0);metric('vulnerable-contacts',s.vulnerableContacts,s.vulnerableContacts>0);metric('red-violations',s.redLights,s.redLights>0);metric('intervention-count',s.interventions);$('fleet-distance').replaceChildren(document.createTextNode(num(s.distance/1000,2)));const unit=document.createElement('small');unit.textContent='km';$('fleet-distance').append(unit);
 $('agent-id').textContent=`${world.mode==='neural'?'NN':'EXPERT'} / ${pad(selected+1)}`;$('agent-title').textContent=`Car ${pad(selected+1)}`;$('agent-speed').textContent=num(c.speed*3.6);$('agent-decision').textContent=c.decision;$('agent-lane').textContent=`${c.lane+1} / 4`;$('agent-gap').textContent=p.gap>=80?'≥80 m':`${num(p.gap,1)} m`;$('agent-offset').textContent=`${num(c.e,2)} m`;$('agent-stop').textContent=p.stopRequired?`${num(p.stopDistance,1)} m`:'Clear';
 $('prediction-label-steer').textContent=world.mode==='expert'?'Expert steering':'Neural steering';$('prediction-label-pedal').textContent=world.mode==='expert'?'Expert pedal':'Neural pedal';const steer=c.prediction.steer,pedal=c.prediction.pedal,applied=c.action.pedal;
 $('neural-steer').textContent=`${steer<0?'R':steer>0?'L':''} ${num(Math.abs(steer)*100)}%`;$('neural-steer-bar').style.left=`${50+steer*49}%`;
 for(const [id,value] of [['neural-pedal',pedal],['applied-pedal',applied]]){$(id).textContent=`${value<0?'Brake':'Throttle'} ${num(Math.abs(value)*100)}%`;$(id+'-bar').style.width=`${Math.abs(value)*100}%`;$(id+'-bar').style.background=value<0?'#e0a184':id==='applied-pedal'?'#a1d8cd':'#d7f878';}
 $('override-note').textContent=c.intervening?`Supervisor intervention: ${c.action.reason}. Steering remains neural.`:world.mode==='expert'?'Scripted expert selected. These are expert outputs.':world.supervisor?'Neural outputs applied. No braking override active.':'Neural-only driving. The braking supervisor is disabled.';$('override-note').classList.toggle('active',c.intervening);
 $('yield-count').textContent=s.yields;$('lane-seconds').textContent=`${num(s.laneSeconds,1)} s`;$('speed-seconds').textContent=`${num(s.speedSeconds,1)} s`;$('headway-seconds').textContent=`${num(s.unsafeSeconds,1)} s`;
 document.querySelectorAll('.car-card').forEach((b,i)=>{const car=world.cars[i];b.children[2].firstChild.textContent=num(car.speed*3.6);b.querySelector('div small').textContent=car.decision;});
 for(const cross of world.crossings){const signal=signalState(world.time,cross.offset),card=$('signal-'+cross.id);if(!card)continue;card.querySelector('i').style.background=signal.phase==='green'?'#b5d980':signal.phase==='amber'?'#e8bd70':'#e79d87';card.querySelector('small').textContent=`${signal.phase.toUpperCase()} ${Math.ceil(signal.remaining)}s · ${signal.walk?'WALK':'WAIT'}`;}
 const log=$('event-log');log.replaceChildren();if(!world.events.length)log.textContent='No contacts or rule violations recorded.';else for(const event of world.events){const row=document.createElement('div');row.textContent=`${clock(event.time)}  ${event.text}`;log.append(row);}
}
function drawChart(rows){const canvas=$('road-loss-chart'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.font='12px monospace';if(!rows?.length){ctx.fillStyle='#91a584';ctx.fillText('No training history in this model.',20,h/2);return;}const logs=rows.flatMap(r=>[Math.log10(Math.max(1e-8,r.loss)),Math.log10(Math.max(1e-8,r.valLoss))]),lo=Math.floor(Math.min(...logs)),hi=Math.max(lo+1,Math.ceil(Math.max(...logs))),x=i=>48+i/Math.max(1,rows.length-1)*(w-62),y=v=>h-25-(Math.log10(Math.max(v,1e-8))-lo)/(hi-lo)*(h-40);
 ctx.strokeStyle='#3b4e34';ctx.fillStyle='#879c78';for(let exponent=lo;exponent<=hi;exponent++){const yy=y(10**exponent);ctx.beginPath();ctx.moveTo(45,yy);ctx.lineTo(w-10,yy);ctx.stroke();ctx.fillText(`1e${exponent}`,3,yy+4);}
 for(const [key,color] of [['loss','#c8e486'],['valLoss','#d7a58a']]){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();rows.forEach((r,i)=>i?ctx.lineTo(x(i),y(r[key])):ctx.moveTo(x(i),y(r[key])));ctx.stroke();}ctx.fillStyle='#8ca07d';ctx.fillText('1',47,h-5);ctx.fillText(String(rows.length),w-40,h-5);$('road-chart-epochs').textContent=`${rows.length} EPOCHS · LOG LOSS`;
}
function renderModel(){if(!model)return;const t=model.training||{};$('road-model-badge').textContent=model.id===baseline?.id?'TRAINED BASELINE':'LOCAL ROAD MODEL';$('road-training-samples').textContent=`${Number(t.samples||0).toLocaleString()} train · ${Number(t.validationSamples||0).toLocaleString()} validation`;$('road-model-epochs').textContent=`${t.epochs||0} epochs`;$('road-model-loss').textContent=`Validation MSE ${num(t.validationLoss,5)}`;drawChart(t.history);renderReport();}
function renderReport(){const rows=report?.simulatorVersion===TRAFFIC_VERSION&&report?.modelId===model?.id&&Array.isArray(report.scenarios)?report.scenarios:null;$('export-road-results').disabled=!rows||busy;const node=$('road-test-table');node.replaceChildren();if(!rows){$('road-test-summary').textContent='This model has no matching evaluation. Run Evaluate fleet.';return;}
 const neural=rows.filter(r=>r.controller==='neural'&&!r.supervisor),assisted=rows.filter(r=>r.controller==='neural'&&r.supervisor);$('road-test-summary').textContent=`${neural.filter(r=>r.passed).length}/${neural.length} neural-only · ${assisted.filter(r=>r.passed).length}/${assisted.length} supervisor-assisted cases passed. Each runs for ${report.secondsPerScenario}s.`;
 const table=document.createElement('table');table.innerHTML='<thead><tr><th>CASE / CARS</th><th>CONTACTS</th><th>RED</th><th>GUARD</th><th>KM</th><th>RESULT</th></tr></thead>';const body=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');const label=`${row.controller==='expert'?'Expert':row.supervisor?'NN + guard':'NN only'} / ${row.cars}${row.dogScenario?' + dog':''}`;[label,`${row.vehicleContacts} / ${row.vulnerableContacts}`,row.redLights,row.interventions,num(row.distanceKm,1),row.passed?'PASS':'FAIL'].forEach((value,i)=>{const td=document.createElement('td');td.textContent=value;if(i===5)td.className=row.passed?'pass':'fail';tr.append(td);});tr.title=`Seed ${row.seed}; lane ${num(row.laneSeconds,2)}s; speeding ${num(row.speedSeconds,2)}s; unsafe headway ${num(row.unsafeSeconds,2)}s; minimum lead gap ${num(row.minGap,2)}m`;body.append(tr);}table.append(body);node.append(table);
}
function setBusy(value){busy=value;for(const id of ['train-road','evaluate-road','export-road-model','import-road-model','restore-road-model','run-traffic','reset-traffic','fleet-mode','car-count','supervisor-toggle','dog-scenario'])$(id).disabled=value||!model;$('cancel-road-training').hidden=!value;$('export-road-results').disabled=value||!report||report.modelId!==model?.id;setRunning(false);}
function startJob(type){if(busy||!model)return;setBusy(true);const current=new Worker(new URL('./road-worker.js',import.meta.url),{type:'module'});worker=current;const rows=[];status(type==='train'?'Starting real Road behavioral cloning…':'Running nine frozen-policy traffic scenarios…',1);
 const finish=()=>{current.terminate();if(worker===current)worker=null;setBusy(false);};
 current.onmessage=({data})=>{if(worker!==current)return;if(data.type==='progress')status(data.stage,data.percent);else if(data.type==='epoch'){rows.push(data.item);drawChart(rows);status(data.stage,data.percent);}else if(data.type==='trained'||data.type==='evaluated'){
  try{if(data.type==='trained'){model=validateTrafficModel(data.model);report=data.report;reset(false);}else report=data.report;persist();renderModel();finish();status(data.type==='trained'&&model.training.bestEpoch===0?'Training complete. Initial weights retained: no validation improvement. Fleet results shown.':`${data.type==='trained'?'Training and evaluation':'Evaluation'} complete. Best validation checkpoint retained; all results shown.`,100);toast('Fleet evaluation complete. Review neural-only and assisted results.');}catch(e){finish();status(e.message,0);}
 }else if(data.type==='error'){finish();drawChart(model.training?.history);status(`Job failed: ${data.message}`,0);toast(data.message);}};
 current.onerror=e=>{if(worker!==current)return;finish();drawChart(model.training?.history);status(`Worker failed: ${e.message}`,0);};current.postMessage({type,model});
}
for(const cross of world.crossings){const card=document.createElement('div');card.className='signal-card';card.id='signal-'+cross.id;const title=document.createElement('span');const dot=document.createElement('i');title.append(dot,document.createTextNode(cross.name));card.append(title,document.createElement('small'));$('signal-grid').append(card);}
$('run-traffic').onclick=()=>setRunning(!running);$('reset-traffic').onclick=()=>{reset();toast('Traffic reset. Session counters restarted.');};$('overview-side').onclick=()=>selectCar(selected,'overview');$('next-car').onclick=()=>selectCar((selected+1)%world.cars.length,'chase');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>selectCar(selected,b.dataset.view));
for(const id of ['car-count','fleet-mode','supervisor-toggle'])$(id).onchange=()=>{reset();toast('New traffic session started with the selected settings.');};
$('dog-scenario').onclick=()=>{requestDog(world,world.cars[selected]);updateUI();toast(`Dog crossing scheduled ahead of Car ${pad(selected+1)}. Watch the crossings.`);};
$('road-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('road-viewport').requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser.');}};
$('export-traffic').onclick=()=>download('road-session.json',{format:'vector-road-session-v1',simulatorVersion:TRAFFIC_VERSION,exportedAt:new Date().toISOString(),modelId:model?.id,settings:settings(),summary:trafficSummary(world),cars:world.cars.map(c=>({id:c.id,lane:c.lane,travel:c.travel,stats:c.stats,prediction:c.prediction,appliedAction:c.action})),events:world.events,history});
$('train-road').onclick=()=>startJob('train');$('evaluate-road').onclick=()=>startJob('evaluate');$('cancel-road-training').onclick=()=>{worker?.terminate();worker=null;setBusy(false);drawChart(model.training?.history);status('Cancelled. Previous active model retained.',0);};
$('export-road-model').onclick=()=>download('road-neural-policy.json',model);$('export-road-results').onclick=()=>download('road-evaluation.json',report);$('import-road-model').onclick=()=>{setRunning(false);$('road-model-file').click();};
$('road-model-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('Model file must be smaller than 2 MB.');const imported=validateTrafficModel(JSON.parse(await file.text()));model=imported;report=null;persist();reset(false);renderModel();setBusy(false);status('Imported Road model. Evaluate the fleet before relying on its behavior.',0);}catch(error){toast(error.message);}finally{e.target.value='';}};
$('restore-road-model').onclick=()=>{model=structuredClone(baseline);report=structuredClone(baselineReport);persist();reset(false);renderModel();setBusy(false);status('Bundled baseline and matching measured results restored.',100);toast('Road baseline restored.');};
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA|BUTTON/.test(document.activeElement?.tagName))return;if(e.code==='Space'){e.preventDefault();setRunning(!running);}else if(e.key.toLowerCase()==='c')selectCar(selected,['overview','chase','pov'][(['overview','chase','pov'].indexOf(view)+1)%3]);else if(e.key.toLowerCase()==='r'&&!busy)reset();else if(e.key==='Escape')setRunning(false);});
document.addEventListener('visibilitychange',()=>{if(document.hidden)setRunning(false);});
async function init(){try{
 const [modelResponse,reportResponse]=await Promise.all([fetch('./models/road-policy.json'),fetch('./models/road-evaluation.json')]);if(!modelResponse.ok)throw new Error('Road policy could not be loaded.');baseline=validateTrafficModel(await modelResponse.json());baselineReport=reportResponse.ok?await reportResponse.json():null;model=structuredClone(baseline);report=structuredClone(baselineReport);
 try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved?.model){model=validateTrafficModel(saved.model);report=saved.report;}}catch{toast('Saved Road model was incompatible. Loaded the bundled baseline.');}
 scene=new RoadScene($('road-viewport'),world,id=>selectCar(id,'chase'));buildFleet();selectCar(0,'overview');$('road-loading').hidden=true;setBusy(false);renderModel();status('Road network ready. Select a car for Chase or Driver POV.',100);setRunning(true);
 let last=performance.now(),accumulator=0,uiTime=0,frames=0,fpsTime=last;
 function frame(now){const elapsed=Math.min((now-last)/1000,.12);last=now;if(running){accumulator+=elapsed*Number($('time-scale').value);let steps=0;while(accumulator>=1/60&&steps<30){const contacts=world.stats.vehicleContacts+world.stats.vulnerableContacts;stepTraffic(world,model);accumulator-=1/60;steps++;const second=Math.floor(world.time);if(second!==lastHistorySecond){lastHistorySecond=second;if(history.length<3600)history.push(trafficSummary(world));}if($('pause-contact').checked&&world.stats.vehicleContacts+world.stats.vulnerableContacts>contacts){setRunning(false);toast('Contact detected. Traffic paused; incident remains in the session log.');break;}}}else accumulator=0;
  scene.update(world,elapsed);if(now-uiTime>180){updateUI();uiTime=now;}frames++;if(now-fpsTime>1000){$('road-fps').textContent=`${Math.round(frames*1000/(now-fpsTime))} FPS`;frames=0;fpsTime=now;}requestAnimationFrame(frame);
 }requestAnimationFrame(frame);
 }catch(error){$('road-loading').textContent=`Road could not start: ${error.message}`;status(error.message,0);$('top-status').textContent='Loading failed';}}
init();
